import type { Metadata } from "next";
import { site } from "./site";
import { MARKETS, MARKET_IDS, type PriceSet } from "./markets";

/** Site-wide social image, generated by app/opengraph-image.tsx (served outside the market rewrite). */
export const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Scenox Commerce: 1000+ products, 48 hours, live on your store",
};

/** Google truncates around 155–160 characters. */
const MAX_DESCRIPTION = 160;

export function pageMeta({
  title,
  description,
  path,
  noIndex,
}: {
  title: string;
  description: string;
  path: string;
  noIndex?: boolean;
}): Metadata {
  if (process.env.NODE_ENV !== "production" && description.length > MAX_DESCRIPTION) {
    console.warn(`[seo] ${path} description is ${description.length} chars (max ${MAX_DESCRIPTION})`);
  }
  const url = `${site.url}${path === "/" ? "" : path}`;
  // Google shows roughly 60 characters; keep the brand suffix only when it still fits
  const branded = `${title} | ${site.name}`;
  const fullTitle = branded.length <= 65 ? branded : title;
  return {
    title: fullTitle,
    description,
    alternates: { canonical: url },
    robots: noIndex ? { index: false, follow: false } : undefined,
    openGraph: {
      title: fullTitle,
      description,
      url,
      siteName: site.name,
      type: "website",
      locale: "en_IN",
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [OG_IMAGE.url],
    },
  };
}

/** ISO country per market, for areaServed / eligibleRegion. */
const MARKET_COUNTRY = { in: "IN", us: "US", uk: "GB", au: "AU" } as const;

export function organizationJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    "@id": `${site.url}/#organization`,
    name: site.name,
    url: site.url,
    email: site.email,
    image: `${site.url}/opengraph-image`,
    description: site.description,
    parentOrganization: {
      "@type": "Organization",
      name: site.parent,
      url: site.parentUrl,
    },
    areaServed: MARKET_IDS.map((m) => ({ "@type": "Country", name: MARKETS[m].label })),
    contactPoint: {
      "@type": "ContactPoint",
      contactType: "sales",
      email: site.email,
      availableLanguage: ["English"],
    },
    knowsAbout: [
      "Shopify bulk product upload",
      "WooCommerce product upload",
      "Magento product upload",
      "BigCommerce product upload",
      "Magento to Shopify migration",
      "Ecommerce catalog management",
      "Product data cleanup",
      "Google Shopping feed management",
      "Ecommerce email marketing",
      "Abandoned cart recovery",
      "WhatsApp automation for ecommerce",
      "AI customer support",
      "AI shopping assistant",
      "AI voice agent",
    ],
  };
}

export function websiteJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": `${site.url}/#website`,
    name: site.name,
    url: site.url,
    publisher: { "@id": `${site.url}/#organization` },
    inLanguage: "en",
  };
}

/** One Offer per market so every currency's starting price is machine-readable. */
function offers(price: PriceSet, path: string) {
  return MARKET_IDS.filter((m) => price[m] != null).map((m) => ({
    "@type": "Offer",
    price: price[m],
    priceCurrency: MARKETS[m].currency,
    eligibleRegion: { "@type": "Country", name: MARKET_COUNTRY[m] },
    url: `${site.url}${path}`,
    availability: "https://schema.org/InStock",
  }));
}

export function serviceJsonLd({
  name,
  description,
  path,
  price,
}: {
  name: string;
  description: string;
  path: string;
  /** starting price per market */
  price?: PriceSet;
}) {
  return {
    "@context": "https://schema.org",
    "@type": "Service",
    name,
    description,
    url: `${site.url}${path}`,
    serviceType: name,
    provider: { "@id": `${site.url}/#organization`, "@type": "Organization", name: site.name, url: site.url },
    areaServed: MARKET_IDS.map((m) => ({ "@type": "Country", name: MARKETS[m].label })),
    ...(price ? { offers: offers(price, path) } : {}),
  };
}

export function servicesItemListJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "ItemList",
    itemListElement: items.map((it, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: it.name,
      url: `${site.url}${it.path}`,
    })),
  };
}

export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((it, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: it.name,
      item: `${site.url}${it.path === "/" ? "" : it.path}`,
    })),
  };
}

export function faqJsonLd(faqs: { q: string; a: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };
}

/** Guides: Article with dates and publisher so answer engines can attribute and date the content. */
export function articleJsonLd(a: { title: string; description: string; path: string; published: string; updated: string; image?: string }) {
  const url = `${site.url}${a.path}`;
  return {
    "@context": "https://schema.org",
    "@type": "Article",
    headline: a.title,
    description: a.description,
    url,
    mainEntityOfPage: url,
    datePublished: a.published,
    dateModified: a.updated,
    image: `${site.url}${a.image ?? OG_IMAGE.url}`,
    author: { "@type": "Organization", "@id": `${site.url}/#organization`, name: site.name, url: site.url },
    publisher: { "@type": "Organization", "@id": `${site.url}/#organization`, name: site.name, url: site.url },
  };
}
